#!/bin/bash
# macOS/Linux: open Terminal in this folder and run:  bash download_art.sh
cd "$(dirname "$0")"; UA="UnwillingSaintArtKit/1.0 (private tabletop book; personal use) curl"
mkdir -p unwilling_saint_art; : > unwilling_saint_art/_failed.txt; total=0; bad=0
get() { total=$((total+1)); d="unwilling_saint_art/$1"; if [ -s "$d" ] && [ $(wc -c <"$d") -gt 2000 ]; then return; fi
  if curl -sfL --retry 3 --retry-delay 3 -A "$UA" -o "$d" "$2" && [ $(wc -c <"$d") -gt 2000 ]; then echo "ok    $1"; else echo "FAIL  $1"; rm -f "$d"; printf "%s\t%s\n" "$1" "$2" >> unwilling_saint_art/_failed.txt; bad=$((bad+1)); fi; sleep 1; }
